INSERT INTO feature VALUES('attributes','attributes','Attributes',NULL,'implemented','ordinary',NULL,'`@[ … ]` attaches registered attributes to a declaration, an unknown name or an ill-typed payload refused by name; a payload may be named, `decomposes(primes = 2)`, where the attribute reads one. `@![ … ]` leading a module''s or a theory''s body attaches its attributes to that module or theory, read with its outer blocks as one list, and one after a member is refused as misplaced under the enclosing name. `@![ … ]` leading a source attaches its attributes to the source, where they reach each declaration of the source, and one after a root child is refused as misplaced.','surface-lowering surface-grammar','corpus/model/attributes/long-attribute-blocks.gandr corpus/pathological/attributes/unknown-attribute.gandr corpus/model/sessions/dialogue-web.gandr corpus/ledger/syntax/inner-attribute-block.gandr crates/surface-lowering/src/lower.rs::a_named_payload_is_spelled_with_its_name_2077 crates/surface-lowering/tests/theory.rs::an_inner_attribute_decorates_its_theory_3586 crates/surface-lowering/src/lower/exits/tests.rs::an_inner_attribute_decorates_its_source','corpus/model/attributes/long-attribute-blocks.gandr',NULL);
